from builtins import str
import re
import json
from past.builtins import basestring
from robot.libraries.BuiltIn import BuiltIn

from taf.ul.trs_e2e_fw.lib.utils.resource_file import load_json_file
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.oam_interface import get_parameter
from taf.ul.trs_e2e_fw.lib.utils.setup_oamops import _setup_oam_ops

logger = BackgroundLogger.Instance()


def replace(target_string, admin_alias=None, variables=''):
    """
    In a given string, this function finds occurrences of built-in robot or admin var patterns and replaces with
     actual values
    Args:
        target_string:

    Returns:

    """
    global variables_to_replace
    if variables != '':
        try:
            variables_to_replace = json.loads(variables)
            logger.debug("Variables for replacement: {}".format(variables_to_replace))
        except Exception:
            BuiltIn().fail("Fail :: Incorrect value given for variables :{}".format(variables))
    else:
        variables_to_replace = dict()
    global global_admin_alias
    global_admin_alias = admin_alias
    if isinstance(target_string, basestring):
        pattern_object = re.compile(r"\$?\{.*?\}")
        # matches ${dscp} or {dhcp} like patterns
        return pattern_object.sub(_get_string_to_replace, target_string)
    return target_string


def _get_string_to_replace(match_object):
    string_to_be_replaced = match_object.group()
    logger.debug("string to be replaced: {}".format(string_to_be_replaced))
    if string_to_be_replaced.startswith('$'):
        variable_in_dict = string_to_be_replaced[2:-1]
        logger.debug("Searching {} in variable replacement dictinary".format(
            variable_in_dict))
        if variable_in_dict in variables_to_replace:
            variable_value = variables_to_replace[variable_in_dict]
            logger.debug("Value being replaced:{0} type: {1}".format(variable_value, type(variable_value)))
        else:
            variable_value = BuiltIn().get_variable_value(string_to_be_replaced, '0')
            logger.debug("Builtin Variable Value: {0} type: {1}".format(variable_value, type(variable_value)))
        return str(variable_value)
    else:
        string_to_be_replaced = string_to_be_replaced.replace('{', '').replace('}', '')     # Removes { }
        if 'ue_ip' in string_to_be_replaced:
            return global_vars.ue_ip_dict[string_to_be_replaced]
        else:
            return _get_value_from_admin(string_to_be_replaced)


def _get_value_from_admin(mapping_name):
    global global_admin_alias
    admin_alias = _setup_oam_ops(alias=global_admin_alias)
    param_path = _get_param_path_from_mapping(mapping_name)
    admin_value = get_parameter(param_path=param_path, alias=admin_alias)
    if not isinstance(admin_value, basestring):
        logger.error('Expected to get a string for {}, but got {} from ADMIN'.format(mapping_name, admin_value))
        raise Exception('Expected string from ADMIN for {}, but got {}'.format(mapping_name, type(admin_value)))
    logger.debug('Variable {0} :admin_value: {1}'.format(mapping_name, admin_value))
    return admin_value


def _get_param_path_from_mapping(mapping_name):
    param_path_mapping_dict = load_json_file('param_path_mapping.json')
    param_path = param_path_mapping_dict[mapping_name]
    pattern_object = re.compile(r"\$?\{.*?\}")
    # matches ${dscp} or {dhcp} like patterns
    return pattern_object.sub(_get_string_to_replace, param_path)
